solutionCode:
def distance(a, b):
    dx = a[0] - b[0]
    dy = a[1] - b[1]
    if dx < 0:
        dx = -dx
    if dy < 0:
        dy = -dy
    return dx + dy

def supply_lead(player, target, rivals):
    if len(rivals) == 0:
        return None
    nearest = distance(rivals[0], target)
    for rival in rivals:
        steps = distance(rival, target)
        if steps < nearest:
            nearest = steps
    return nearest - distance(player, target)

